text:
Here's your water tracker with a goal of 8 glasses. Tap **+ Add glass** after each one. It starts fresh each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body { font-family: Segoe UI, sans-serif; margin: 0; padding: 24px; background: #f2f8fc; color: #12324a; text-align: center; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #date { color: #5b7a90; font-size: 14px; margin-bottom: 20px; }
  #count { font-size: 56px; font-weight: 600; }
  #goal { color: #5b7a90; margin-bottom: 16px; }
  #bar { height: 14px; background: #d6e8f4; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  #fill { height: 100%; width: 0; background: #2f8fd8; transition: width .25s; }
  #glasses { font-size: 28px; letter-spacing: 4px; margin-bottom: 20px; min-height: 36px; }
  button { font-size: 16px; padding: 10px 18px; margin: 4px; border: 0; border-radius: 8px; cursor: pointer; }
  #add { background: #2f8fd8; color: #fff; }
  #sub, #reset { background: #dbe9f3; color: #12324a; }
  #msg { margin-top: 16px; font-weight: 600; color: #1f8a4c; min-height: 22px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0</div>
  <div id="goal">of 8 glasses</div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button id="add">+ Add glass</button>
  <button id="sub">− Remove</button>
  <button id="reset">Reset</button>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var n = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.day === today) n = saved.n || 0;
  } catch (e) {}
  function save() {
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }
  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var g = "";
    for (var i = 0; i < Math.max(GOAL, n); i++) g += i < n ? "💧" : "○";
    document.getElementById("glasses").textContent = g;
    document.getElementById("msg").textContent = n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " to go";
  }
  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("sub").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
